{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "MEDIUM",
      "explanation": "The aws_s3_bucket_public_access_block resource for document_storage is missing the block_public_acls attribute set to true, which is necessary to fully prevent public access."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket = aws_s3_bucket.document_storage.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Added block_public_acls = true to aws_s3_bucket_public_access_block.document_storage to prevent public ACLs on the S3 bucket."
}
